function decision(input){const p={...D.backhauls.NB,...input.nb},g={...D.backhauls['5G'],...input.g5};return LPWANEngine.evaluate({payloadBytes:input.emergency?D.gateway.emergency_bytes:D.gateway.telemetry_bytes,emergency:input.emergency,batteryPct:input.battery,algorithm:input.algorithm,backhauls:{NB:p,'5G':g},availability:{NB:input.nbAvail,'5G':input.g5Avail},modemStates:{NB:input.nbState||'SLEEP','5G':input.g5State||'SLEEP'},queueSeconds:input.queueSeconds||{},activeRemaining:input.activeRemaining||{},cpuElapsed:input.cpuElapsed??0});}
function candidateTable(d){return `<div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Available</th><th>Predicted delay</th><th>Deadline</th><th>Energy</th><th>Reliability</th><th>Bandwidth</th><th>Feasibility</th></tr></thead><tbody>${d.candidates.map(c=>`<tr><td>${c.id==='NB'?'NB-IoT':'5G NR'}</td><td>${c.available?'Yes':'No'}</td><td class="num">${fmt(c.predictedLatency,5)} s</td><td class="num">${fmt(c.deadline,1)} s</td><td class="num">${fmt(c.instantEnergy,6)} J</td><td class="num">${fmt(c.reliability,1)}%</td><td class="num">${c.bandwidth>=1e6?fmt(c.bandwidth/1e6,0)+' Mbps':fmt(c.bandwidth/1e3,0)+' kbps'}</td><td><span class="badge ${c.feasible?'green':c.available?'amber':'red'}">${c.feasible?'FEASIBLE':c.available?'DEADLINE FAIL':'UNAVAILABLE'}</span></td></tr>`).join('')}</tbody></table></div>`;}
function topsisTrace(d){if(!d.topsis)return `<div class="callout warn">${esc(d.reason)} TOPSIS is bypassed when zero or one candidate is feasible.</div>`;if(d.topsis.rows.length<2)return `<div class="callout">${esc(d.reason)}</div>`;const t=d.topsis;return `<div class="grid two"><div class="control"><b>Original decision matrix</b><div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>Candidate</th><th>Latency</th><th>Energy</th><th>Reliability</th><th>Bandwidth</th></tr></thead><tbody>${t.rows.map(r=>`<tr><td>${r.id}</td>${r.values.map(v=>`<td class="num">${fmt(v,6)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="control"><b>Normalized matrix</b><div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>Candidate</th>${D.weights.criteria.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr><td>${r.id}</td>${r.normalized.map(v=>`<td class="num">${fmt(v,5)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="control"><b>Weighted normalized matrix</b><div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>Candidate</th>${D.weights.criteria.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr><td>${r.id}</td>${r.weighted.map(v=>`<td class="num">${fmt(v,6)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="control"><b>Distances and closeness</b><div class="table-wrap" style="margin-top:8px"><table><thead><tr><th>Candidate</th><th>D⁺</th><th>D⁻</th><th>Cᵢ</th></tr></thead><tbody>${t.rows.map(r=>`<tr><td>${r.id}</td><td class="num">${fmt(r.dPlus,6)}</td><td class="num">${fmt(r.dMinus,6)}</td><td class="num"><b>${fmt(r.closeness,6)}</b></td></tr>`).join('')}</tbody></table></div></div></div><div class="callout good" style="margin-top:10px">Positive ideal: [${t.idealBest.map(x=>fmt(x,6)).join(', ')}]<br>Negative ideal: [${t.idealWorst.map(x=>fmt(x,6)).join(', ')}]<br><b>${esc(d.selected)} selected.</b> ${esc(d.reason)}</div>`;}
function initDemo(seed=2026){return {running:false,time:0,algorithm:'AHP',seed:Number(seed),rng:Number(seed)>>>0,duration:3600,arrival:2,emergencyRatio:.1,battery:100,speed:2,nbAvail:true,g5Avail:true,nbRel:95,g5Rel:99,nbScale:1,g5Scale:1,g5Degraded:false,showPackets:true,event:{type:'none',start:1000,dur:60,active:false,done:false},generated:0,delivered:0,emergGenerated:0,emergDelivered:0,qos:0,reliability:0,outage:0,queueDrops:0,cpuEnergy:0,nbEnergy:0,g5Energy:0,totalEnergy:0,switches:0,nbSel:0,g5Sel:0,lastSel:null,packets:[],events:[],modem:{NB:{state:'SLEEP',available:true,busyUntil:0,wakeUntil:0,tailUntil:0,tasks:[],setup:0,energy:0},'5G':{state:'SLEEP',available:true,busyUntil:0,wakeUntil:0,tailUntil:0,tasks:[],setup:0,energy:0}},stats:{latSum:0,latN:0}};}
function rand(){demo.rng=(1664525*demo.rng+1013904223)>>>0;return demo.rng/4294967296;}
function evt(title,desc,type='info'){demo.events.unshift({title,desc,type,t:demo.time});demo.events=demo.events.slice(0,24);}
function modemParams(id){const p=D.backhauls[id];return {...p,reliability_pct:id==='NB'?demo.nbRel:demo.g5Rel,base_latency_s:id==='5G'&&demo.g5Degraded?.15:p.base_latency_s,setup_energy_j:p.setup_energy_j*(id==='NB'?demo.nbScale:demo.g5Scale),tx_power_w:p.tx_power_w*(id==='NB'?demo.nbScale:demo.g5Scale)};}
function updateModems(){for(const id of ['NB','5G']){const m=demo.modem[id];if(!m.available){m.state='UNAVAILABLE';continue;}m.tasks=m.tasks.filter(x=>x.status==='IN_FLIGHT_TX'||x.status==='IN_FLIGHT_BH_Q');const active=m.tasks.find(x=>x.start<=demo.time&&x.finish>demo.time);if(demo.time<m.wakeUntil)m.state='WAKING';else if(active)m.state='ACTIVE';else if(demo.time<m.tailUntil)m.state='IDLE_TAIL';else m.state='SLEEP';}}
function finishJobs(){for(const id of ['NB','5G']){const m=demo.modem[id];for(const task of [...m.tasks]){if(task.finish<=demo.time&&task.status!=='DONE'){if(!m.available){task.packet.status='DROP_OUTAGE';demo.outage++;evt('Packet dropped by outage',`${task.packet.id} on ${id}`,'danger');}else if(rand()*100>task.reliability){task.packet.status='DROP_RELIABILITY';demo.reliability++;evt('Reliability drop',`${task.packet.id} · configured reliability ${task.reliability}%`,'danger');}else{task.packet.status='DELIVERED';demo.delivered++;demo.stats.latSum+=task.actualLatency;demo.stats.latN++;if(task.packet.emergency)demo.emergDelivered++;evt('Packet delivered',`${task.packet.id} via ${id} · ${fmt(task.actualLatency*1000,2)} ms actual demo latency`,'success');}task.status='DONE';task.packet.stage=task.packet.status;if(id==='NB')demo.nbEnergy+=task.txEnergy;else demo.g5Energy+=task.txEnergy;demo.totalEnergy+=task.txEnergy;demo.battery=Math.max(0,demo.battery-(task.txEnergy/D.gateway.battery_capacity_j)*100);}}m.tasks=m.tasks.filter(x=>x.status!=='DONE');updateModems();}}
function applyEvent(){const e=demo.event;if(!e||e.type==='none'||e.done)return;const end=e.start+e.dur;if(!e.active&&demo.time>=e.start&&demo.time<end){e.active=true;if(e.type==='NB_OUTAGE'||e.type==='5G_OUTAGE'){const id=e.type==='NB_OUTAGE'?'NB':'5G',m=demo.modem[id];if(id==='NB')demo.nbAvail=false;else demo.g5Avail=false;m.available=false;for(const t of m.tasks){if(t.status!=='DONE'){t.packet.status='DROP_OUTAGE';t.status='DONE';demo.outage++;}}m.tasks=[];m.busyUntil=demo.time;evt(`${id} outage started`,`Scheduled event: ${id} unavailable for ${e.dur}s.`,'danger');}else if(e.type==='E_LAT_DEGRADE'){demo.g5Degraded=true;evt('5G latency degradation started','5G base latency changed from 20 ms to 150 ms in the browser demo.','warn');}}if(e.active&&demo.time>=end){if(e.type==='NB_OUTAGE'){demo.nbAvail=true;demo.modem.NB.available=true;demo.modem.NB.state='SLEEP';evt('NB-IoT recovered','Scheduled NB-IoT outage ended.','success');}else if(e.type==='5G_OUTAGE'){demo.g5Avail=true;demo.modem['5G'].available=true;demo.modem['5G'].state='SLEEP';evt('5G recovered','Scheduled 5G outage ended.','success');}else if(e.type==='E_LAT_DEGRADE'){demo.g5Degraded=false;evt('5G base latency restored','Returned to 20 ms.','success');}e.done=true;e.active=false;}}
function decisionForDemo(emergency,payload){const nb=demo.modem.NB,g=demo.modem['5G'];const backlog=id=>demo.modem[id].tasks.filter(t=>t.start>demo.time&&t.status!=='DONE').reduce((s,t)=>s+t.service,0);const active=id=>{const m=demo.modem[id];return Math.max(0,m.busyUntil-demo.time);};return LPWANEngine.evaluate({payloadBytes:payload,emergency,batteryPct:demo.battery,algorithm:demo.algorithm,backhauls:{NB:modemParams('NB'),'5G':modemParams('5G')},availability:{NB:demo.nbAvail,'5G':demo.g5Avail},modemStates:{NB:nb.state,'5G':g.state},queueSeconds:{NB:backlog('NB'),'5G':backlog('5G')},activeRemaining:{NB:nb.state==='ACTIVE'?active('NB'):nb.state==='WAKING'?Math.max(0,nb.wakeUntil-demo.time):0,'5G':g.state==='ACTIVE'?active('5G'):g.state==='WAKING'?Math.max(0,g.wakeUntil-demo.time):0},cpuElapsed:.005});}
function stepPacket(){if(!demo)return;const next=demo.time+(-Math.log(Math.max(1e-9,1-rand()))/Math.max(.05,demo.arrival));if(next>demo.duration){demo.time=demo.duration;stop();evt('Simulation horizon reached',`Stopped at ${demo.duration}s; remaining in-flight jobs are not counted as delivered.`,'info');render();return;}demo.time=next;applyEvent();finishJobs();updateModems();const emergency=rand()<demo.emergencyRatio,payload=emergency?D.gateway.emergency_bytes:D.gateway.telemetry_bytes;demo.generated++;if(emergency)demo.emergGenerated++;demo.cpuEnergy+=D.gateway.cpu_processing_s*D.gateway.cpu_power_w;demo.totalEnergy+=D.gateway.cpu_processing_s*D.gateway.cpu_power_w;demo.battery=Math.max(0,demo.battery-(D.gateway.cpu_processing_s*D.gateway.cpu_power_w/D.gateway.battery_capacity_j)*100);
const dec=decisionForDemo(emergency,payload);const packet={id:`BRW-${String(demo.generated).padStart(5,'0')}`,time:demo.time,emergency,payload,deadline:dec.deadline,state:dec.state,stage:'IN_FLIGHT_CPU_PROC',selected:dec.selected,predicted:dec.selected?dec.candidates.find(x=>x.id===dec.selected).predictedLatency:null,status:'IN_FLIGHT_CPU_PROC',decision:dec};
evt('Packet received',`${packet.id} · ${emergency?'EMERGENCY':'TELEMETRY'} · ${payload} bytes`,'info');evt('QoS feasibility checked',`NB ${dec.nb.feasible?'feasible':dec.nb.available?'deadline-infeasible':'unavailable'} · 5G ${dec.g5.feasible?'feasible':dec.g5.available?'deadline-infeasible':'unavailable'}`,dec.feasible.length?'success':'danger');evt('Gateway state classified',`${dec.state} · battery ${fmt(demo.battery,1)}%`,'info');
if(!dec.selected){packet.status='DROP_QOS';packet.stage=packet.status;demo.qos++;evt('QoS drop','No candidate is available and predicted within the packet deadline.','danger');}
else{const id=dec.selected,m=demo.modem[id],p=modemParams(id),cand=dec.candidates.find(x=>x.id===id);if(m.tasks.length>=D.gateway.backhaul_queue_limit){packet.status='DROP_QUEUE_OVERFLOW_BH';packet.stage=packet.status;demo.queueDrops++;evt('Backhaul queue overflow',`${id} queue reached ${D.gateway.backhaul_queue_limit} packets.`,'danger');}else{const sleeping=m.state==='SLEEP',setup=sleeping?p.setup_delay_s:m.state==='WAKING'?Math.max(0,m.wakeUntil-demo.time):0,service=(payload*8)/p.bandwidth_bps+p.base_latency_s,start=Math.max(demo.time+setup,m.busyUntil),finish=start+service,setupEnergy=sleeping?p.setup_energy_j:0,txEnergy=p.tx_power_w*((payload*8)/p.bandwidth_bps);if(sleeping){m.wakeUntil=demo.time+p.setup_delay_s;m.setup++;m.energy+=setupEnergy;demo.totalEnergy+=setupEnergy;if(id==='NB')demo.nbEnergy+=setupEnergy;else demo.g5Energy+=setupEnergy;demo.battery=Math.max(0,demo.battery-(setupEnergy/D.gateway.battery_capacity_j)*100);}m.busyUntil=finish;m.tailUntil=finish+p.idle_tail_s;const task={packet,start,finish,service,txEnergy,reliability:p.reliability_pct,actualLatency:finish-packet.time,status:'IN_FLIGHT_TX'};m.tasks.push(task);packet.status='IN_FLIGHT_BH_Q';packet.stage='IN_FLIGHT_BH_Q';packet.selected=id;packet.predicted=cand.predictedLatency;packet.instantEnergy=cand.instantEnergy;if(id==='NB')demo.nbSel++;else demo.g5Sel++;if(demo.lastSel&&demo.lastSel!==id)demo.switches++;demo.lastSel=id;evt('Backhaul selected',`${id==='NB'?'NB-IoT':'5G NR'} chosen by ${demo.algorithm}.`,'success');evt('Packet entered backhaul queue',`${packet.id} · ${id} · predicted ${fmt(cand.predictedLatency*1000,2)}ms`,'info');}}
demo.packets.unshift(packet);demo.packets=demo.packets.slice(0,60);finishJobs();updateModems();render();}
function start(){if(!demo)demo=initDemo();if(demo.running)return;demo.running=true;timer=setInterval(stepPacket,Math.max(100,850/demo.speed));render();}
function stop(){if(timer)clearInterval(timer);timer=null;if(demo)demo.running=false;}
function reset(){stop();const seed=demo?.seed??2026;demo=initDemo(seed);render();toast('Browser demonstration reset.');}
function randomScenario(name){const sc=scenarioMeta(name);if(!sc)return;stop();demo=initDemo(demo?.seed??2026);demo.arrival=sc.arrival_rate_pps;demo.emergencyRatio=sc.emergency_ratio;demo.battery=sc.battery_pct;demo.nbRel=100-sc.nb_configured_loss_pct;demo.g5Rel=100-sc.fiveg_configured_loss_pct;demo.nbScale=sc.nb_energy_scale;demo.g5Scale=sc.fiveg_energy_scale;if(sc.events.length){const e=sc.events[0];demo.event={type:e.type,start:e.start_s,dur:e.duration_s,active:false,done:false};demo.duration=Math.max(3600,e.start_s+e.duration_s+1);}render();toast(`${name} configuration loaded in browser demonstration mode; not a source-engine reproduction.`);}
function scheduleEvent(type,start,dur){demo.event={type,start,dur,active:false,done:false};render();toast(`Scheduled ${type} at ${start}s for ${dur}s of simulation time.`);}

function renderOverview(){
  const nb=base('NB'),g5=base('5G'),ahp=base('AHP'),M=D.tsc_matrix;
  return `${pageHead('Command centre','A unified view of the LoRaWAN gateway, cellular backhaul decision pipeline and recorded research evidence.',`<button class="btn" data-action="walkthrough">Guided project walkthrough</button><button class="btn primary" data-view="lab">Open interactive lab ↗</button>`)}
  <div class="grid four">${kpi('PRIMARY DATA ROWS',num(D.source.primary_rows),'24 scenarios · 30 seeds · 6 strategies','cyan')}${kpi('BASELINE STRATEGIES',num(D.source.algorithm_count),'Recorded 30-seed comparison','violet')}${kpi('TSC PAIRED TRACES',num(M.paired_traces),'30 conditions × 30 seeds','blue')}${kpi('OUTAGE PILOT ROWS',num(D.source.supplementary_outage_rows),'Separate five-seed supplement','amber')}</div>
  <div class="grid two" style="margin-top:14px">
    <div class="panel"><div class="panel-head"><div><h3>Project at a glance</h3><div class="panel-sub">Gateway-centric LPWAN–cellular backhaul selection</div></div><span class="badge green">DATA LOADED</span></div><p class="help" style="font-size:13px">LoRaWAN-originated traffic reaches a logical edge gateway. The gateway checks packet deadlines and backhaul availability, classifies the operating state, applies AHP criterion weights and uses TOPSIS to rank feasible NB-IoT and 5G candidates.</p><div class="section-line"></div><div class="status-list"><div class="status-row"><span>Device access</span><b>LoRaWAN · logical endpoints</b></div><div class="status-row"><span>Decision location</span><b>Edge gateway</b></div><div class="status-row"><span>Selectable backhauls</span><b>NB-IoT and 5G NR</b></div><div class="status-row"><span>Decision pipeline</span><b>QoS → state/AHP → TOPSIS</b></div><div class="status-row"><span>6G profile</span><b class="amber">Exploratory · not selectable</b></div></div><div class="section-actions" style="margin-top:12px"><button class="btn small" data-view="topology">View architecture</button><button class="btn small" data-view="explainer">Understand the system</button><button class="btn small" data-view="impact">See modifications & impact</button></div></div>
    <div class="panel"><div class="panel-head"><div><h3>Recorded baseline results</h3><div class="panel-sub">Fixed NB-IoT reference compared with fixed 5G and adaptive AHP-TOPSIS</div></div></div><div class="grid three">${kpi('NB-IoT PDR',pct(nb.PDR_Mean),'Reference','amber')}${kpi('5G PDR',pct(g5.PDR_Mean),'Fixed 5G control','cyan')}${kpi('ADAPTIVE PDR',pct(ahp.PDR_Mean),'AHP-TOPSIS','violet')}</div><div class="status-list" style="margin-top:12px"><div class="status-row"><span>Fixed NB-IoT mean latency</span><b>${fmt(nb.Avg_Lat_s_Mean,4)} s</b></div><div class="status-row"><span>Fixed 5G mean latency</span><b>${fmt(g5.Avg_Lat_s_Mean,4)} s</b></div><div class="status-row"><span>Adaptive mean latency</span><b>${fmt(ahp.Avg_Lat_s_Mean,4)} s</b></div></div><div class="callout warn" style="margin-top:12px">Research caveat: fixed 5G and adaptive AHP-TOPSIS have identical primary metrics; 5G was selected in all recorded AHP ranking decisions. The result does not establish adaptive superiority over fixed 5G.</div></div>
  </div>
  <div class="grid two" style="margin-top:14px"><div class="panel"><div class="panel-head"><div><h3>Gateway-to-cloud path</h3><div class="panel-sub">Logical architecture used by the simulation</div></div><button class="btn small" data-view="topology">Open topology ↗</button></div><div class="topology-wrap">${architecture('5G',false)}</div></div><div class="panel"><div class="panel-head"><div><h3>Choose a workspace</h3><div class="panel-sub">The dashboard keeps recorded evidence separate from live demonstrations</div></div></div><div class="status-list"><button class="btn" style="width:100%;text-align:left" data-view="lab">Interactive lab — run the browser demonstration</button><button class="btn" style="width:100%;text-align:left" data-view="decision">Decision inspector — inspect AHP/TOPSIS calculations</button><button class="btn" style="width:100%;text-align:left" data-view="analytics">Performance analytics — explore archived results</button><button class="btn" style="width:100%;text-align:left" data-view="experiments">Experiment explorer — inspect all scenarios</button><button class="btn" style="width:100%;text-align:left" data-view="integrity">Data integrity — review provenance and limitations</button></div><div class="callout" style="margin-top:12px">Browser demonstration metrics are illustrative. Recorded experiment data remains unchanged. The optional SimPy bridge runs separately and requires the sibling Framework directory.</div></div></div>`;
}

function renderLab(){const st=demo?LPWANEngine.classifyState(false,demo.battery):'NORMAL';const pdr=demo&&demo.generated?demo.delivered/demo.generated:0,mean=demo&&demo.stats.latN?demo.stats.latSum/demo.stats.latN:NaN;return `${pageHead('Interactive network laboratory','Seeded browser-side packet demonstration. It shares the source decision equations and model inputs, but it is not the original SimPy event scheduler.',`<span class="badge amber">BROWSER DEMO · NOT SIMPY</span><button class="btn" data-action="simpy-run">Run selected strategy in SimPy ↗</button><button class="btn primary" data-action="simpy-tsc">Run Two-Timescale Controller ↗</button>`)}
<div class="grid" style="grid-template-columns:minmax(0,1.4fr) minmax(300px,.85fr);margin-bottom:14px"><div class="panel"><div class="panel-head"><div><h3>Simulation controls</h3><div class="panel-sub">Start, pause, resume, step packets and reset the simulation clock.</div></div></div><div class="field-row"><button class="btn primary" data-action="start" ${demo.running?'disabled':''}>▶ Start / Resume</button><button class="btn" data-action="pause" ${!demo.running?'disabled':''}>Ⅱ Pause</button><button class="btn" data-action="step">＋ Step one packet</button><button class="btn danger" data-action="reset">↺ Reset</button><button class="btn" data-action="export-demo">↓ Export browser CSV</button></div><div class="control-grid" style="margin-top:13px"><div class="control"><label class="control-label">Algorithm</label><select id="lab-algo" class="select">${D.algorithms.map(x=>`<option value="${x.id}" ${x.id===demo.algorithm?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="control"><label class="control-label">Primary scenario preset</label><select id="lab-scenario" class="select"><option value="">Manual settings</option>${D.scenario_meta.map(s=>`<option value="${s.name}">${s.name}</option>`).join('')}</select></div><div class="control"><label class="control-label">Seed</label><input class="input" id="lab-seed" type="number" min="0" max="2147483647" value="${demo.seed}"></div><div class="control"><label class="control-label">Duration (simulated seconds)</label><input class="input" id="lab-duration" type="number" min="10" max="3600" value="${demo.duration}"></div><div class="control"><label class="control-label">Speed</label><input id="lab-speed" class="range" type="range" min="1" max="5" value="${demo.speed}"><small>${demo.speed}× packet step pace</small></div><div class="control"><label class="control-label">Arrival rate</label><input id="lab-arrival" class="range" type="range" min=".5" max="8" step=".5" value="${demo.arrival}"><small>${fmt(demo.arrival,1)} packets/s</small></div><div class="control"><label class="control-label">Emergency share</label><input id="lab-emergency" class="range" type="range" min="0" max="60" step="5" value="${demo.emergencyRatio*100}"><small>${fmt(demo.emergencyRatio*100,0)}%</small></div><div class="control"><label class="control-label">Gateway battery</label><input id="lab-battery" class="range" type="range" min="0" max="100" value="${demo.battery}"><small>${fmt(demo.battery,0)}%</small></div><div class="control"><label class="control-label">NB configured reliability</label><input id="lab-nb-rel" class="range" type="range" min="80" max="100" value="${demo.nbRel}"><small>${demo.nbRel}%</small></div><div class="control"><label class="control-label">5G configured reliability</label><input id="lab-g5-rel" class="range" type="range" min="80" max="100" value="${demo.g5Rel}"><small>${demo.g5Rel}%</small></div><div class="control"><label class="control-label">Packet animation</label><label><input type="checkbox" id="lab-animation" ${demo.showPackets?'checked':''}> Show animated flow</label></div></div><div class="section-line"></div><div class="field-row"><label class="control-label">Scheduled event</label><select class="select" id="lab-event"><option value="none">None</option><option value="NB_OUTAGE">NB-IoT outage</option><option value="5G_OUTAGE">5G outage / recovery (separate demo)</option><option value="E_LAT_DEGRADE">5G latency degradation (150 ms)</option></select><input id="lab-event-start" class="input" style="max-width:115px" type="number" min="0" max="3590" value="${demo.event.start}"><input id="lab-event-dur" class="input" style="max-width:100px" type="number" min="1" max="600" value="${demo.event.dur}"><button class="btn small" data-action="schedule">Schedule</button><button class="btn small" data-action="out-nb">${demo.nbAvail?'Disable':'Restore'} NB</button><button class="btn small" data-action="out-g5">${demo.g5Avail?'Disable':'Restore'} 5G</button></div><div class="help" style="margin-top:8px">Primary presets use 5G latency degradation at 1,000s for 60s and NB-IoT outage at 2,000s for 30s. The 5G outage is supplementary and separate. Browser demo timings are approximate; use the optional SimPy bridge for source-engine runs.</div></div>
<div class="panel"><div class="panel-head"><div><h3>Browser simulation KPIs</h3><div class="panel-sub">Not archived research metrics</div></div><span class="badge ${demo.running?'green':'amber'}">${demo.running?'RUNNING':'PAUSED / READY'}</span></div><div class="grid two">${kpi('PDR',pct(pdr),'Delivered / generated','green')}${kpi('MEAN DELIVERED LATENCY',Number.isFinite(mean)?fmt(mean*1000,2)+' ms':'—','Browser task-scheduling approximation','cyan')}${kpi('GENERATED',num(demo.generated),'Demo packets','violet')}${kpi('TOTAL ENERGY',fmt(demo.totalEnergy,3)+' J','CPU + setup + transmission estimate','amber')}</div><div class="section-line"></div><div class="status-list"><div class="status-row"><span class="label">Simulation clock</span><strong>${fmt(demo.time,2)} / ${demo.duration}s</strong></div><div class="status-row"><span class="label">Delivered / QoS / reliability</span><strong>${demo.delivered} / ${demo.qos} / ${demo.reliability}</strong></div><div class="status-row"><span class="label">Outage / queue drops</span><strong>${demo.outage} / ${demo.queueDrops}</strong></div><div class="status-row"><span class="label">NB / 5G selections</span><strong>${demo.nbSel} / ${demo.g5Sel}</strong></div><div class="status-row"><span class="label">Backhaul-label switches</span><strong>${demo.switches}</strong></div><div class="status-row"><span class="label">Emergency PDR</span><strong>${demo.emergGenerated?pct(demo.emergDelivered/demo.emergGenerated):'—'}</strong></div><div class="status-row"><span class="label">Gateway state</span><b class="violet">${LPWANEngine.classifyState(false,demo.battery)}</b></div></div><div class="section-line"></div><div class="status-row"><span class="label">Battery remaining</span><strong>${fmt(demo.battery,2)}%</strong></div><div class="track"><div class="fill" style="width:${demo.battery}%;background:${demo.battery<20?C.red:C.green}"></div></div></div></div>
<div class="grid two" style="margin-bottom:14px"><div class="panel"><div class="panel-head"><div><h3>Five-layer packet route</h3><div class="panel-sub">Selected cellular path is highlighted; simplified logical topology.</div></div></div><div class="topology-wrap">${architecture(demo.lastSelected||'5G',demo.showPackets)}</div><div class="status-row"><span class="label">NB availability</span><b class="${demo.nbAvail?'green':'red'}">${demo.nbAvail?'AVAILABLE':'OUTAGE'}</b></div><div class="status-row"><span class="label">5G availability</span><b class="${demo.g5Avail?'green':'red'}">${demo.g5Avail?'AVAILABLE':'OUTAGE'}</b></div></div>
<div class="panel"><div class="panel-head"><div><h3>Modem state and queues</h3><div class="panel-sub">SLEEP → WAKING → ACTIVE → IDLE_TAIL → SLEEP</div></div></div>${['NB','5G'].map(id=>{const m=demo.modem[id];return `<div class="status-row"><span><i class="status-dot ${id==='NB'?'nbdot':'g5dot'}"></i><b>${id==='NB'?'NB-IoT':'5G NR'}</b></span><span class="badge ${m.state==='UNAVAILABLE'?'red':m.state==='ACTIVE'?'green':'cyan'}">${m.state}</span></div><div class="status-row"><span class="label">Pending / active packet tasks</span><b>${m.tasks.length}</b></div><div class="metric-bar"><span class="label">Accumulated energy</span><div class="track"><div class="fill" style="width:${Math.min(100,m.energy/15*100)}%;background:${id==='NB'?C.NB:C['5G']}"></div></div><b>${fmt(m.energy,2)} J</b></div>`;}).join('')}<div class="section-line"></div><div class="status-row"><span class="label">CPU energy</span><b>${fmt(demo.cpuEnergy,3)} J</b></div></div></div>
<div class="grid two"><div class="panel"><h3>Recent packet inspector</h3><div class="panel-sub">Select a packet for its path decision and feasibility evidence.</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Packet</th><th>Type</th><th>Arrival</th><th>Path</th><th>Prediction</th><th>Status</th></tr></thead><tbody>${demo.packets.slice(0,18).map(p=>`<tr data-packet="${p.id}"><td class="packet-id">${p.id}</td><td>${p.emergency?'EMERGENCY':'TELEMETRY'}</td><td>${fmt(p.time,2)} s</td><td>${p.selected||'—'}</td><td>${p.predicted===null?'—':fmt(p.predicted*1000,2)+' ms'}</td><td><span class="badge ${p.status==='DELIVERED'?'green':p.status.startsWith('DROP')?'red':'amber'}">${p.status}</span></td></tr>`).join('')||'<tr><td colspan="6">No packets yet.</td></tr>'}</tbody></table></div></div><div class="panel"><h3>Live event timeline</h3><div class="panel-sub">Simulation time advances independently of the computer clock.</div><div class="timeline" style="margin-top:12px">${demo.events.slice(0,14).map(e=>`<div class="event ${e.type}"><i class="mark"></i><div><b>${esc(e.title)}</b><p>${esc(e.desc)}</p></div><time>${fmt(e.t,2)}s</time></div>`).join('')||'<div class="empty">No events recorded.</div>'}</div></div></div><div class="callout warn" style="margin-top:14px">This browser event model is a visual demonstration, not an execution of SimPy. Its packet logs and metrics must not be described as new primary experiment results. Use the optional API action above for a fresh independent SimPy run.</div>`;}
function renderDecision(){const d=lastDecision||decision({emergency:false,battery:100,algorithm:'AHP',nbAvail:true,g5Avail:true});return `${pageHead('Decision inspector','Inspect availability, predicted deadline feasibility, AHP priorities and each TOPSIS calculation step. The default candidate audit uses initial-sleep telemetry inputs.')}<div class="grid two"><div class="panel"><h3>Packet and gateway inputs</h3><div class="field"><label class="control-label">Packet class</label><select id="di-type" class="select"><option value="telemetry">Telemetry · 50 B · deadline 10s</option><option value="emergency">Emergency · 200 B · deadline 1s</option></select></div><div class="field"><label class="control-label">Battery <span id="di-bat-value">100%</span></label><input id="di-bat" class="range" type="range" min="0" max="100" value="100"></div><div class="field"><label class="control-label">Algorithm</label><select id="di-algo" class="select">${D.algorithms.map(a=>`<option value="${a.id}" ${a.id==='AHP'?'selected':''}>${a.name}</option>`).join('')}</select></div><div class="status-row"><span>NB-IoT available</span><input type="checkbox" id="di-nb" checked></div><div class="status-row"><span>5G available</span><input type="checkbox" id="di-g5" checked></div><button class="btn primary" style="width:100%;margin-top:12px" data-action="di-calc">Calculate transparent decision</button></div><div class="panel"><h3>Feasibility comparison</h3><div id="di-summary">${candidateTable(d)}</div><div class="callout" style="margin-top:10px">Feasibility rule: available(i) = 1 and predicted_delay(p,i) ≤ packet deadline. TOPSIS is never run on an empty feasible set.</div><div id="di-final" style="margin-top:12px"></div></div></div><div class="grid two" style="margin-top:14px"><div class="panel"><h3>Gateway state and AHP weights</h3><div id="di-state"><span class="badge violet">${d.state}</span><p class="help">${D.weights.states[d.state].condition}</p>${weightsBars(d.state)}</div><div class="section-line"></div><h3>AHP pairwise matrix</h3><div id="di-ahp"></div><div class="help">Aᵢⱼ = wᵢ / wⱼ. The matrix is reciprocal and perfectly consistent by construction; this is not expert preference validation.</div></div><div class="panel"><h3>TOPSIS trace</h3><div id="di-topsis">${topsisTrace(d)}</div></div></div>`;}
function renderBackhaul(){return `${pageHead('Backhaul comparison','Two logical model alternatives with configured simulator assumptions, plus their recorded 30-seed baseline results.')}<div class="grid two">${['NB','5G'].map(id=>{const p=D.backhauls[id],r=base(id);return `<div class="panel" style="border-top:3px solid ${id==='NB'?C.NB:C['5G']}"><h3>${id==='NB'?'NB-IoT / LTE-EPC-style':'5G NR / gNB / 5GC-style'}</h3><div class="grid two" style="margin-top:12px">${[['Bandwidth',id==='NB'?'66 kbps':'100 Mbps'],['Base latency',p.base_latency_s+' s'],['Wake/setup delay',p.setup_delay_s+' s'],['Setup energy',p.setup_energy_j+' J'],['Transmit power',p.tx_power_w+' W'],['Configured reliability',p.reliability_pct+'%']].map(([a,b])=>`<div class="control"><small>${a}</small><div class="number-large" style="font-size:20px">${b}</div></div>`).join('')}</div><div class="section-line"></div><div class="status-row"><span>Baseline PDR</span><b>${pct(r.PDR_Mean)}</b></div><div class="status-row"><span>Mean latency</span><b>${fmt(r.Avg_Lat_s_Mean,4)} s</b></div><div class="status-row"><span>P95 latency</span><b>${fmt(r['95th_Lat_s_Mean'],4)} s</b></div><div class="status-row"><span>Total energy</span><b>${fmt(r.Total_Eng_J_Mean,2)} J</b></div><div class="status-row"><span>Emergency PDR</span><b>${pct(r.Emerg_PDR_Mean)}</b></div></div>`;}).join('')}</div><div class="grid two" style="margin-top:14px">${panel('Baseline packet delivery ratio','30-seed recorded mean',chartBars('PDR',['NB-IoT','5G NR'],[{id:'NB',v:[base('NB').PDR_Mean,null]},{id:'5G',v:[null,base('5G').PDR_Mean]}],{max:1,labels:true,valueFmt:pct}))}${panel('Baseline total energy','Configured energy boundary: CPU + setup + transmission',chartBars('Energy',['NB-IoT','5G NR'],[{id:'NB',v:[base('NB').Total_Eng_J_Mean,null]},{id:'5G',v:[null,base('5G').Total_Eng_J_Mean]}],{max:150,labels:true,valueFmt:x=>fmt(x,2)+' J'}))}</div><div class="callout warn" style="margin-top:14px">Values are illustrative simulator settings and source-model results. They are not universal NB-IoT or 5G commercial performance specifications. Sleep and idle-tail leakage are excluded from reported totals.</div>`;}
function renderAnalytics(){const loads=['0.5','1.0','2.0','4.0','8.0'],loadRows=loads.map(x=>D.load_sweep.filter(r=>r.Scenario===`G_LOAD_${x}`)),loadAvg=id=>loadRows.map(rows=>{const a=rows.filter(r=>r.Algorithm===id);return a.length?a.reduce((s,r)=>s+r.PDR,0)/a.length*100:null;});const relBy=id=>D.reliability_sensitivity.filter(x=>x.Backhaul===(id==='NB'?'NB-IoT':'5G')).sort((a,b)=>a.Configured_Loss_Pct-b.Configured_Loss_Pct);return `${pageHead('Performance analytics','Recorded data from the supplied 4,320-row primary matrix and separate supplementary experiments.')}<div class="grid two">${panel('Baseline PDR · six strategies','30-seed baseline means',chartBars('Baseline PDR',D.algorithm_order.map(name),[{id:'NB',v:D.algorithm_order.map(id=>base(id).PDR_Mean*100),name:'PDR (%)'}],{max:100,labels:true,valueFmt:x=>fmt(x,2)+'%'}))}${panel('Baseline mean latency','Use log scale: NB-IoT differs by orders of magnitude.',chartBars('Log10 baseline mean latency',D.algorithm_order.map(name),[{id:'LAT',v:D.algorithm_order.map(id=>Math.log10(base(id).Avg_Lat_s_Mean)),name:'log10(seconds)'}],{min:-2,max:.6,labels:true,tick:x=>'10^'+fmt(x,1),valueFmt:x=>Math.pow(10,x).toFixed(4)+'s'}))}${panel('Baseline total energy','Energy metric is defined by the project accounting boundary.',chartBars('Baseline total energy',['NB-IoT','Fixed 5G','Adaptive'],[{id:'NB',v:[base('NB').Total_Eng_J_Mean,null,null]},{id:'5G',v:[null,base('5G').Total_Eng_J_Mean,null]},{id:'AHP',v:[null,null,base('AHP').Total_Eng_J_Mean]}],{max:150,labels:true,valueFmt:x=>fmt(x,2)+'J'}))}${panel('Decision execution microbenchmark','Separate microbenchmark; not per-run Algo_Time_Mean_us.',chartBars('Mean execution time (µs)',D.overhead.map(x=>x.Algorithm),[{id:'AHP',v:D.overhead.map(x=>x.Mean_Overhead_us),name:'Mean overhead'}],{max:600,labels:true,valueFmt:x=>fmt(x,1)+'µs'}))}${panel('Offered-load sensitivity','PDR vs 0.5, 1, 2, 4 and 8 packets/s.',chartLine('PDR vs offered load',loads,[{id:'NB',v:loadAvg('NB')},{id:'5G',v:loadAvg('5G')},{id:'AHP',v:loadAvg('AHP')}],{max:100,tick:x=>fmt(x,0)+'%',valueFmt:x=>fmt(x,2)+'%'}))}${panel('Reliability sensitivity','Measured result by configured packet-loss setting.',chartLine('PDR vs configured packet loss',['1%','5%','10%'],[{id:'NB',v:relBy('NB').map(x=>x.PDR_Mean*100)},{id:'5G',v:relBy('5G').map(x=>x.PDR_Mean*100)}],{max:100,tick:x=>fmt(x,0)+'%',valueFmt:x=>fmt(x,2)+'%'}))}${panel('AHP selected path · primary matrix','5,768,175 logged ranking decisions; 5G is selected in all of them.',donut([{label:'5G selected',value:5768175,color:C['5G']},{label:'NB selected',value:0,color:C.NB}],'100%'))}${panel('Pareto classification','Denominator includes all ranking calls; 96.13% of both-feasible calls are 5G-dominant.',donut([{label:'5G dominates',value:4827117,color:C['5G']},{label:'Neither dominates',value:194210,color:C.AHP},{label:'Only one feasible',value:746848,color:C.NB}],'5.77M'))}</div><div class="grid two" style="margin-top:14px">${panel('Supplementary outage / recovery selection','Separate five-seed pilot (30 strategy-seed records).',chartBars('NB-IoT fallback during 5G outage',['Latency-first','Energy-first','Static TOPSIS','Adaptive AHP'],['LAT','ENG','TOP','AHP'].map(id=>({id,v:[(D.outage_selection.find(x=>x.Algorithm===id)||{}).NB_Selections_During_5G_Outage_Mean||0]})),{max:65,labels:true,valueFmt:x=>fmt(x,1)}))}${panel('Outage pilot outcomes','Exploratory proof-of-behaviour; not a broad superiority claim.',`<div class="status-row"><span>Adaptive PDR</span><b>${pct(D.outage_summary.find(x=>x.Algorithm==='AHP')?.PDR)}</b></div><div class="status-row"><span>Fixed-5G PDR</span><b>${pct(D.outage_summary.find(x=>x.Algorithm==='5G')?.PDR)}</b></div><div class="status-row"><span>NB fallback during outage</span><b>57.2 mean</b></div><div class="status-row"><span>5G selections during outage</span><b>0</b></div><div class="status-row"><span>5G selections after recovery</span><b>3,098.2 mean</b></div><div class="status-row"><span>Backhaul label changes</span><b>2.0 mean / seed</b></div><div class="callout warn" style="margin-top:10px">The 5-seed pilot is not merged into the primary experiment and is not standards-compliant handover validation.</div>`)} </div><div class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Baseline six-strategy table</h3><div class="panel-sub">Means over 30 paired seeds</div></div><button class="btn small" data-action="export-primary">Download primary CSV</button></div><div class="table-wrap"><table><thead><tr><th>Strategy</th><th>PDR</th><th>Mean latency</th><th>P95 latency</th><th>Energy</th><th>Emergency PDR</th><th>QoS drops</th></tr></thead><tbody>${D.baseline.map(r=>`<tr><td>${name(r.Algorithm)}</td><td>${pct(r.PDR_Mean)}</td><td>${fmt(r.Avg_Lat_s_Mean,4)}s</td><td>${fmt(r['95th_Lat_s_Mean'],4)}s</td><td>${fmt(r.Total_Eng_J_Mean,2)}J</td><td>${pct(r.Emerg_PDR_Mean)}</td><td>${fmt(r.QoS_Drop_Mean,1)}</td></tr>`).join('')}</tbody></table></div></div>`;}
function renderExperiments(){const cats=[...new Set(D.scenario_meta.map(x=>x.category))],sc=scenarioMeta(scenario)||D.scenario_meta[0],rows=D.scenario_results.filter(x=>x.Scenario===sc.name).sort((a,b)=>D.algorithm_order.indexOf(a.Algorithm)-D.algorithm_order.indexOf(b.Algorithm));return `${pageHead('Experiment explorer','Explore the 24 primary configurations, seed-averaged results and event parameters. The 5G outage pilot and 800 offline sensitivity cases remain separate.',`<button class="btn" data-action="export-scenario">Export scenario CSV</button>`)}<div class="grid" style="grid-template-columns:270px minmax(0,1fr)"><div class="panel"><label class="control-label">Scenario category</label><select id="scenario-category" class="select"><option>All categories</option>${cats.map(x=>`<option ${x===window.scenarioCat?'selected':''}>${x}</option>`).join('')}</select><div class="scenario-grid" style="grid-template-columns:1fr;margin-top:12px">${D.scenario_meta.filter(x=>!window.scenarioCat||window.scenarioCat==='All categories'||x.category===window.scenarioCat).map(x=>`<button class="scenario-btn ${x.name===sc.name?'active':''}" data-scenario="${x.name}"><b>${x.name}</b><small>${x.category}</small></button>`).join('')}</div></div><div class="panel"><h3>${sc.name}</h3><div class="panel-sub">${sc.category}</div><div class="grid four" style="margin-top:12px">${[['Arrival rate',sc.arrival_rate_pps+' pps'],['Emergency share',fmt(sc.emergency_ratio*100,0)+'%'],['Battery',sc.battery_pct+'%'],['NB / 5G loss',sc.nb_configured_loss_pct+'% / '+sc.fiveg_configured_loss_pct+'%']].map(x=>`<div class="control"><small class="muted">${x[0]}</small><div class="number-large" style="font-size:18px">${x[1]}</div></div>`).join('')}</div><div class="section-line"></div><div class="status-row"><span>Energy scales · NB / 5G</span><b>${sc.nb_energy_scale}× / ${sc.fiveg_energy_scale}×</b></div>${sc.events.length?`<div class="callout warn" style="margin:10px 0">${esc(sc.events[0].detail)} At ${sc.events[0].start_s}s for ${sc.events[0].duration_s}s.</div>`:''}<h3 style="margin-top:14px">Recorded six-strategy outcomes</h3><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Algorithm</th><th>PDR</th><th>Emergency PDR</th><th>Mean latency</th><th>P95</th><th>Energy</th><th>NB select</th><th>5G select</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${name(r.Algorithm)}</td><td>${pct(r.PDR)}</td><td>${pct(r.Emerg_PDR)}</td><td>${fmt(r.Avg_Lat_s,4)}s</td><td>${fmt(r['95th_Lat_s'],4)}s</td><td>${fmt(r.Total_Eng_J,2)}J</td><td>${fmt(r.NB_Sel,1)}</td><td>${fmt(r['5G_Sel'],1)}</td></tr>`).join('')}</tbody></table></div><div class="callout warn" style="margin-top:12px">Recorded results are 30-seed means from the supplied primary CSV. This scenario explorer does not rerun the archived experiment.</div></div></div>`;}
function renderExplainer(){return `${pageHead('Project explainer','A guided explanation of existing technologies, your implemented framework, equations, experiment scope and limitations.',`<button class="btn primary" data-view="impact">Our modifications & impact ↗</button>`)}<div class="grid two"><div class="panel"><h3>Existing technologies vs project contribution</h3><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Existing element</th><th>What this project implements</th></tr></thead><tbody><tr><td>LoRaWAN</td><td>LoRaWAN-originated traffic as input to a logical gateway; detailed PHY/MAC abstracted.</td></tr><tr><td>NB-IoT</td><td>LTE/EPC-style cellular backhaul candidate; not treated as 5G NR.</td></tr><tr><td>5G NR / 5GC</td><td>Logical 5G backhaul candidate represented by simplified model parameters.</td></tr><tr><td>AHP / TOPSIS</td><td>State-specific design vectors and TOPSIS applied after hard feasibility filtering.</td></tr><tr><td>LPWAN-cellular research</td><td>Five-layer gateway selection pipeline, six strategy baselines and simulation experiments.</td></tr></tbody></table></div></div><div class="panel"><h3>Five-layer implementation boundary</h3><div class="topology-wrap">${architecture('5G',false)}</div><p class="help">The architecture is a logical simulation abstraction, not a standards-complete deployment topology.</p></div></div><div class="grid two" style="margin-top:14px"><div class="panel"><h3>QoS feasibility</h3><div class="formula">F(p) = { i ∈ {NB, 5G} : available(i)=1 and D̂(p,i) ≤ T(p) }</div><p class="help">Emergency deadline: 1 s. Telemetry deadline: 10 s. If no candidate satisfies both conditions, the packet is recorded as a QoS drop and TOPSIS is not executed.</p></div><div class="panel"><h3>AHP and TOPSIS</h3><div class="formula">aᵢⱼ = wᵢ / wⱼ<br>rᵢⱼ = xᵢⱼ / √Σᵢxᵢⱼ²<br>vᵢⱼ = wⱼ rᵢⱼ<br>Cᵢ = Dᵢ⁻ / (Dᵢ⁺ + Dᵢ⁻)</div><p class="help">Latency and energy are cost criteria; reliability and bandwidth are benefit criteria. AHP vectors are design-specified, not expert-survey-derived.</p></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Research limitations</h3><div class="panel-sub">What is simulated, what is abstracted and what remains future work</div></div><button class="btn small" data-view="impact">See measured modification impact ↗</button></div><div class="grid two" style="margin-top:10px">${D.limitations.map(x=>`<div class="callout warn">${esc(x)}</div>`).join('')}</div></div>`;}

function renderImpact(){
  const nb=base('NB'),g5=base('5G'),ahp=base('AHP'),M=D.tsc_matrix;
  const fmtPctDelta=(x)=>`${x>=0?'+':''}${fmt(x,2)} pp`;
  const baseRows=[
    ['PDR',pct(nb.PDR_Mean),pct(g5.PDR_Mean),pct(ahp.PDR_Mean),fmtPctDelta((ahp.PDR_Mean-nb.PDR_Mean)*100)],
    ['Mean latency',fmt(nb.Avg_Lat_s_Mean,4)+' s',fmt(g5.Avg_Lat_s_Mean,4)+' s',fmt(ahp.Avg_Lat_s_Mean,4)+' s',fmt((1-ahp.Avg_Lat_s_Mean/nb.Avg_Lat_s_Mean)*100,2)+'% lower vs NB'],
    ['P95 latency',fmt(nb['95th_Lat_s_Mean'],4)+' s',fmt(g5['95th_Lat_s_Mean'],4)+' s',fmt(ahp['95th_Lat_s_Mean'],4)+' s',fmt((1-ahp['95th_Lat_s_Mean']/nb['95th_Lat_s_Mean'])*100,2)+'% lower vs NB'],
    ['Emergency PDR',pct(nb.Emerg_PDR_Mean),pct(g5.Emerg_PDR_Mean),pct(ahp.Emerg_PDR_Mean),fmtPctDelta((ahp.Emerg_PDR_Mean-nb.Emerg_PDR_Mean)*100)],
    ['Modelled energy',fmt(nb.Total_Eng_J_Mean,2)+' J',fmt(g5.Total_Eng_J_Mean,2)+' J',fmt(ahp.Total_Eng_J_Mean,2)+' J',fmt((ahp.Total_Eng_J_Mean/nb.Total_Eng_J_Mean-1)*100,2)+'% vs NB']
  ];
  const a=M.aggregate['AHP-TOPSIS'],t=M.aggregate.TSC;
  const matrixRows=[
    ['Pooled PDR',pct(a.pooled_pdr),pct(t.pooled_pdr),`${fmt((t.pooled_pdr-a.pooled_pdr)*100,4)} pp`],
    ['Mean of condition-level mean latency',fmt(a.mean_latency_s,5)+' s',fmt(t.mean_latency_s,5)+' s',fmt((t.mean_latency_s/a.mean_latency_s-1)*100,2)+'%'],
    ['Mean of condition-level P95 latency',fmt(a.mean_p95_s,5)+' s',fmt(t.mean_p95_s,5)+' s',fmt((t.mean_p95_s/a.mean_p95_s-1)*100,2)+'%'],
    ['Pooled emergency PDR',pct(a.emergency_pdr),pct(t.emergency_pdr),fmt((t.emergency_pdr-a.emergency_pdr)*100,4)+' pp'],
    ['Total modelled energy',fmt(a.total_energy_j,3)+' J',fmt(t.total_energy_j,3)+' J',fmt((t.total_energy_j/a.total_energy_j-1)*100,4)+'%'],
    ['Mean selector computation',fmt(a.mean_decision_us,3)+' µs',fmt(t.mean_decision_us,3)+' µs',fmt((t.mean_decision_us/a.mean_decision_us-1)*100,2)+'%']
  ];
  const sigRows=M.significant_end_to_end.map(r=>`<tr><td>${r.metric.replaceAll('_',' ')}</td><td>${r.load_pps} pps</td><td>${Math.round(r.emergency_ratio*100)}%</td><td>${r.outage}</td><td>${fmt(r.baseline_mean,4)}</td><td>${fmt(r.tsc_mean,4)}</td><td>${fmt(r.relative_change_pct,2)}%</td><td>${Number(r.holm_p).toPrecision(3)}</td></tr>`).join('');
  return `${pageHead('Our modifications & performance impact','Baseline implementation, new controller, unified backhaul abstraction and the evidence from the completed paired experiments.',`<span class="badge green">RECORDED EXPERIMENTS</span><button class="btn" data-view="explainer">Project explainer ↗</button>`)}
  <div class="callout warn"><b>Evidence boundary:</b> the primary 4,320-row experiment, the original outage pilot, the 30-seed TSC validation and the 900-trace TSC matrix are separate datasets. “Before” means the fixed-NB-IoT simulator reference, not a physical pre-deployment measurement.</div>
  <div class="grid two" style="margin-top:14px">
    <div class="panel"><h3>Original/reference system</h3><div class="status-list"><div class="status-row"><span>Access technology</span><b>LoRaWAN (abstracted)</b></div><div class="status-row"><span>Backhaul candidates</span><b>NB-IoT and 5G NR</b></div><div class="status-row"><span>Decision point</span><b>Logical edge gateway</b></div><div class="status-row"><span>Selection pipeline</span><b>Feasibility → state → AHP → TOPSIS</b></div><div class="status-row"><span>Original strategies</span><b>Six</b></div></div></div>
    <div class="panel"><h3>What the upgrade added</h3><div class="status-list"><div class="status-row"><span>Session/burst decision</span><b class="green">TSC preference</b></div><div class="status-row"><span>Traffic estimate</span><b>EWMA + Poisson cluster estimate</b></div><div class="status-row"><span>Packet-level protection</span><b>Emergency override + fallback</b></div><div class="status-row"><span>Candidate abstraction</span><b>Profile / adapter interface</b></div><div class="status-row"><span>6G profile</span><b>Exploratory, non-selectable</b></div></div></div>
  </div>
  <div class="panel" style="margin-top:14px"><h3>Primary baseline: fixed NB-IoT vs fixed 5G vs adaptive AHP-TOPSIS</h3><p class="help">30 paired seeds, 24 configurations and six strategies (4,320 raw metric rows). The adaptive AHP selector chose 5G in all 5,768,175 logged primary ranking calls, so it matched fixed-5G network metrics.</p><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Fixed NB-IoT</th><th>Fixed 5G</th><th>Adaptive AHP</th><th>Change vs NB</th></tr></thead><tbody>${baseRows.map(r=>`<tr>${r.map((x,i)=>`<td>${i===0?`<b>${x}</b>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="callout warn" style="margin-top:10px">The improvement versus fixed NB-IoT is largely explained by choosing 5G. The primary experiment does not show that adaptive AHP-TOPSIS outperforms fixed 5G.</div></div>
  <div class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>New TSC paired matrix</h3><div class="panel-sub">30 operating conditions · 30 seeds per condition · 900 paired traces · 1,800 algorithm runs</div></div><span class="badge green">COMPLETED</span></div><div class="grid four">${kpi('CONDITIONS',num(M.conditions),'5 loads × 2 emergency shares × 3 outages','cyan')}${kpi('PAIRED TRACES',num(M.paired_traces),'30 seeds per condition','blue')}${kpi('DECISION RECORDS',num(M.decision_records),'TSC controller log','violet')}${kpi('WALL RUNTIME',fmt(M.wall_runtime_s,1)+' s','Completed experiment','amber')}</div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Metric</th><th>AHP-TOPSIS</th><th>TSC</th><th>Descriptive change</th></tr></thead><tbody>${matrixRows.map(r=>`<tr>${r.map((x,i)=>`<td>${i===0?`<b>${x}</b>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="help">Aggregate averages span heterogeneous operating conditions; condition-wise paired tests are the inferential basis.</p></div>
  <div class="grid three" style="margin-top:14px">
    ${panel('Where TSC is statistically different','Wilcoxon paired tests; Holm correction across 180 tests',`<div class="status-row"><span>Selector time</span><b class="green">${M.significant_counts.Mean_Decision_Time_us}/30</b></div><div class="status-row"><span>Mean latency</span><b>${M.significant_counts.Mean_Latency_s}/30</b></div><div class="status-row"><span>P95 latency</span><b>${M.significant_counts.P95_Latency_s}/30</b></div><div class="status-row"><span>Modelled energy</span><b>${M.significant_counts.Total_Modelled_Energy_J}/30</b></div><div class="status-row"><span>PDR</span><b>${M.significant_counts.PDR}/30</b></div><div class="status-row"><span>Emergency PDR</span><b>${M.significant_counts.Emergency_PDR}/30</b></div>`)}
    ${panel('What the matrix does not establish','Important negative findings',`<div class="callout warn">No significant PDR or emergency-PDR gain after correction.</div><div class="callout warn">No reduction in packet-selection changes: 2,436 for TSC vs 2,404 for AHP.</div><div class="callout warn">Full-matrix modelled energy is 0.0736% higher for TSC.</div>`)}
    ${panel('Scope and reproducibility','Separation of evidence types',`<div class="status-row"><span>Original primary</span><b>4,320 rows</b></div><div class="status-row"><span>TSC matrix</span><b>900 paired traces</b></div><div class="status-row"><span>Browser demo</span><b>Illustrative only</b></div><div class="status-row"><span>6G profile</span><b>Non-selectable</b></div>`)}
  </div>
  <div class="panel" style="margin-top:14px"><h3>Condition-wise statistically significant end-to-end results</h3><p class="help">Values are condition-level means. Relative change is (TSC / baseline − 1) × 100; negative values favour TSC for latency and modelled energy.</p><div class="table-wrap"><table><thead><tr><th>Metric</th><th>Load</th><th>Emergency</th><th>Outage</th><th>AHP mean</th><th>TSC mean</th><th>Change</th><th>Holm p</th></tr></thead><tbody>${sigRows}</tbody></table></div></div>
  <div class="grid two" style="margin-top:14px">${panel('Before vs after changes','What was added to the baseline',`<ul><li>Session/burst preference rather than independent persistent switching on every packet.</li><li>EWMA inter-arrival estimate and Poisson expected-cluster estimate.</li><li>Emergency packet override and forced fallback.</li><li>Common backhaul profile/adapter contract.</li><li>IMT-2030 profile template, explicitly non-selectable.</li></ul>`)}${panel('Model limitations','What must not be overclaimed',`<ul><li>No physical radio/modem or hardware energy measurements.</li><li>Idle-tail/sleep leakage and switching energy excluded.</li><li>No full EPC/5GC, N3IWF, ATSSS or LoRa PHY/MAC.</li><li>No predictive queue-risk or MMPP model.</li><li>No implemented 6G radio/core or performance data.</li></ul>`)}</div>`;
}

function renderViva(){const q=QAS.filter(x=>(x[0]+' '+x[1]).toLowerCase().includes(vivaTerm.toLowerCase()));return `${pageHead('Viva mode','Search and rehearse technically defensible answers.')}<div class="field" style="max-width:480px"><input class="input" id="viva-search" placeholder="Search examiner questions…" value="${esc(vivaTerm)}"></div><div class="grid two">${q.map((x,i)=>`<div class="qa" data-qa><b>${esc(x[0])}</b><div class="answer">${esc(x[1])}</div></div>`).join('')||'<div class="empty">No questions found.</div>'}</div>`;}
function renderIntegrity(){const M=D.tsc_matrix;return `${pageHead('Data integrity and provenance','Source-of-truth mapping, experiment boundaries and final submission scope.')}<div class="grid four">${kpi('PRIMARY RAW ROWS',num(D.source.primary_rows),'24 × 30 × 6','cyan')}${kpi('TSC CONDITIONS',num(M.conditions),'Paired evaluation','blue')}${kpi('TSC PAIRED TRACES',num(M.paired_traces),'30 seeds per condition','violet')}${kpi('TSC DECISIONS',num(M.decision_records),'Controller records','amber')}</div><div class="grid two"><div class="panel"><h3>Source-of-truth map</h3><div class="status-row"><span>Canonical code</span><b>Framework/src/core + simulation</b></div><div class="status-row"><span>Primary raw data</span><b>Framework/results/raw/</b></div><div class="status-row"><span>Paired baseline stats</span><b>Framework/results/processed/</b></div><div class="status-row"><span>TSC matrix data</span><b>Framework/results/supplementary/two_timescale/multi_operating_point/</b></div><div class="status-row"><span>Architecture profiles</span><b>Framework/results/supplementary/backhaul_architecture/</b></div></div><div class="panel"><h3>Research integrity status</h3><div class="status-row"><span>Primary rows</span><b class="green">4,320 archived</b></div><div class="status-row"><span>AHP ranking calls</span><b>5,768,175</b></div><div class="status-row"><span>Primary AHP 5G selection</span><b>100%</b></div><div class="status-row"><span>TSC matrix conditions complete</span><b class="green">30 / 30</b></div><div class="status-row"><span>Statistical tests</span><b>180 · Holm corrected</b></div><div class="status-row"><span>Primary full matrix rerun</span><b class="amber">Audited, not rerun</b></div><div class="status-row"><span>6G profile</span><b class="amber">Non-selectable template</b></div></div></div><div class="panel" style="margin-top:14px"><h3>Execution modes and evidence boundaries</h3><div class="grid two"><div class="callout good"><b>Archived research data</b><br>Primary and supplementary CSV/JSON outputs included in the package.</div><div class="callout warn"><b>Interactive browser demonstration</b><br>Simplified frontend model; not SimPy results.</div><div class="callout"><b>Optional local SimPy bridge</b><br>Runs fresh independent simulations with installed dependencies; does not modify archived data.</div><div class="callout warn"><b>6G scope</b><br>IMT-2030 profile template only; no 6G radio, core or performance metrics.</div></div></div><div class="section-actions" style="margin-top:14px"><button class="btn" data-action="download-manifest">Download source manifest</button><button class="btn" data-action="download-primary">Download primary raw CSV</button><button class="btn" data-action="download-paired">Download paired statistics CSV</button><button class="btn" data-action="download-selection">Download selection audit CSV</button></div>`;}

function renderTopology(){return `${pageHead('Network topology','Gateway-centric logical integration. The access network and cellular backhaul are distinct; 6G is an exploratory profile only.')}<div class="panel"><div class="panel-head"><h3>Unified LPWAN–cellular architecture</h3><span class="badge">LOGICAL SIMULATION ABSTRACTION</span></div><div class="topology-wrap" style="margin-top:12px">${architecture('5G',true)}</div><div class="grid four" style="margin-top:12px"><button class="btn" data-layer="1">1 · Device</button><button class="btn" data-layer="2">2 · Gateway</button><button class="btn" data-layer="3">3 · Orchestration</button><button class="btn" data-layer="4">4 · Backhaul</button></div><div class="panel" id="layer-detail" style="margin-top:12px"><h3>Layer 3 · Edge orchestration</h3><p class="help">Packet classification, CPU queue, availability/deadline feasibility, battery state, state-dependent AHP weights, TOPSIS ranking and the separate TSC session/packet controller form the decision point.</p></div></div><div class="grid two" style="margin-top:14px"><div class="panel"><h3>Access and backhaul are distinct</h3><p class="help">LoRaWAN remains the endpoint access link to a logical gateway. The selected cellular backhaul carries aggregated traffic onward. This simulator does not convert LoRaWAN frames into native NR waveforms or implement a converged cellular core.</p><div class="status-row"><span>NB-IoT profile</span><b class="green">Implemented / selectable</b></div><div class="status-row"><span>5G NR profile</span><b class="green">Implemented / selectable</b></div></div><div class="future"><h3>IMT-2030 / 6G extension profile</h3><p class="help">The common profile contract includes a non-selectable exploratory template with ITU usage-scenario labels. It has no numeric radio metrics, adapter, radio interface, core implementation or performance results. This is architecture extensibility, not 6G implementation.</p><span class="badge amber">NON-SELECTABLE · EXPLORATORY</span></div></div>`;}

function render(){if(!D)return;const meta={overview:['RESEARCH CONTROL CENTRE','Command centre'],topology:['NETWORK VISUALISATION','Network topology'],lab:['INTERACTIVE DEMONSTRATION','Interactive lab'],decision:['ALGORITHM INSPECTION','Decision inspector'],backhaul:['CANDIDATE NETWORKS','Backhaul comparison'],analytics:['ARCHIVED EXPERIMENT DATA','Performance analytics'],experiments:['PRIMARY EXPERIMENT MATRIX','Experiment explorer'],explainer:['SYSTEM DOCUMENTATION','Project explainer'],impact:['RESEARCH CONTRIBUTION','Our modifications & impact'],viva:['PRESENTATION SUPPORT','Viva mode'],integrity:['PROVENANCE & SCOPE','Data integrity']}[view];$('#kicker').textContent=meta[0];$('#page-title').textContent=meta[1];$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const fn={overview:renderOverview,topology:renderTopology,lab:renderLab,decision:renderDecision,backhaul:renderBackhaul,analytics:renderAnalytics,experiments:renderExperiments,explainer:renderExplainer,impact:renderImpact,viva:renderViva,integrity:renderIntegrity}[view];$('#view-root').innerHTML=fn();}
function setView(v){view=v;render();window.scrollTo(0,0);$('#sidebar').classList.remove('open');}
function modal(title,body){$('#modal-root').innerHTML=`<div class="modal-back" data-close><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h3>${title}</h3><button class="close" data-close>×</button></div>${body}</div></div>`;}
function inspectPacket(id){const p=demo.packets.find(x=>x.id===id);if(!p)return;modal(`Packet inspector · ${p.id}`,`<div class="grid two"><div class="control"><small>Type</small><div class="number-large">${p.emergency?'EMERGENCY':'TELEMETRY'}</div></div><div class="control"><small>Status</small><div class="number-large">${p.status}</div></div><div class="control"><small>Payload / deadline</small><b>${p.payload} B / ${p.deadline}s</b></div><div class="control"><small>Gateway state</small><b>${p.state}</b></div><div class="control"><small>Selected path</small><b>${p.selected||'None'}</b></div><div class="control"><small>Predicted delay</small><b>${p.predicted===null?'—':fmt(p.predicted,6)+'s'}</b></div></div><div class="section-line"></div>${candidateTable(p.decision)}<div class="callout warn" style="margin-top:12px">Browser-side simulation log only. Not an archived research row.</div>`);}
function evaluateInspector(){const emergency=$('#di-type').value==='emergency',battery=Number($('#di-bat').value),algorithm=$('#di-algo').value;lastDecision=decision({emergency,battery,algorithm,nbAvail:$('#di-nb').checked,g5Avail:$('#di-g5').checked});$('#di-summary').innerHTML=candidateTable(lastDecision);$('#di-state').innerHTML=`<span class="badge violet">${lastDecision.state}</span><p class="help">${D.weights.states[lastDecision.state].condition}</p>${weightsBars(lastDecision.state)}<div class="section-line"></div><div class="table-wrap"><table><thead><tr><th>Criterion</th>${D.weights.criteria.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${LPWANEngine.pairwiseMatrix(lastDecision.weights).map((r,i)=>`<tr><td>${D.weights.criteria[i]}</td>${r.map(v=>`<td>${fmt(v,4)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#di-topsis').innerHTML=topsisTrace(lastDecision);$('#di-final').innerHTML=`<div class="callout ${lastDecision.selected?'good':'danger'}"><b>${lastDecision.selected||'No backhaul selected'}</b><br>${esc(lastDecision.reason)}</div>`;}
function download(name,text,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function csvDownload(url,name){fetch(url).then(r=>{if(!r.ok)throw Error('Unable to load source file');return r.blob();}).then(b=>{const a=document.createElement('a'),u=URL.createObjectURL(b);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}).catch(e=>toast(e.message,true));}
function demoCsv(){const rows=[['packet_id','simulation_time_s','type','payload_bytes','deadline_s','gateway_state','selected_backhaul','predicted_latency_s','status'],...demo.packets.map(p=>[p.id,p.time,p.emergency?'EMERGENCY':'TELEMETRY',p.payload,p.deadline,p.state,p.selected||'',p.predicted??'',p.status])];download('browser_demo_packets.csv',rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');}
function startFreshSimpy(algorithmOverride=null){
  const selectedAlgorithm=algorithmOverride||demo.algorithm;
  const eventMap={NB_OUTAGE:'nb_outage','5G_OUTAGE':'5g_outage',E_LAT_DEGRADE:'5g_latency_degrade'};
  const selectedDuration=selectedAlgorithm==='TSC'?Math.min(demo.duration,180):demo.duration;
  const useDefaultTscOutage=selectedAlgorithm==='TSC'&&demo.event.type==='none'&&selectedDuration>65;
  const eventType=useDefaultTscOutage?'5G_OUTAGE':demo.event.type;
  const eventStart=useDefaultTscOutage?40:demo.event.start;
  const eventDuration=useDefaultTscOutage?20:demo.event.dur;
  const eventFits=eventType!=='none'&&eventStart+eventDuration<=selectedDuration;
  fetch('http://127.0.0.1:8001/api/simpy/run',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({algorithm:selectedAlgorithm,arrival_rate_pps:demo.arrival,emergency_ratio:demo.emergencyRatio,battery_pct:demo.battery,seed:demo.seed,duration_s:selectedDuration,nb_available:demo.nbAvail,fiveg_available:demo.g5Avail,nb_reliability_pct:demo.nbRel,fiveg_reliability_pct:demo.g5Rel,nb_energy_scale:demo.nbScale,fiveg_energy_scale:demo.g5Scale,event:eventFits?(eventMap[eventType]||'none'):'none',event_start_s:eventStart,event_duration_s:eventDuration})
  }).then(async r=>{
    const j=await r.json();
    if(!r.ok)throw Error(j.detail||'SimPy backend failed');
    const ctrl=j.metrics.controller_diagnostics;
    const diagnosticRows=ctrl?`<div class="status-row"><span>Persistent controller switches</span><b>${ctrl.persistent_switches}</b></div><div class="status-row"><span>Packet QoS overrides</span><b>${ctrl.packet_qos_overrides}</b></div><div class="status-row"><span>Forced fallbacks</span><b>${ctrl.forced_fallbacks}</b></div><div class="status-row"><span>Session index</span><b>${ctrl.session_index}</b></div>`:'';
    modal(selectedAlgorithm==='TSC'?'Fresh Two-Timescale SimPy run':'Fresh independent SimPy run',`<span class="badge green">ACTUAL PYTHON / SIMPY SOURCE</span><p class="help">${selectedAlgorithm==='TSC'?'Bounded 180-second maximum validation run; session preference plus packet-level QoS override. A default 5G outage is included when the sample window permits.':'New run; not merged into archived CSVs.'}</p><div class="grid three">${kpi('PDR',pct(j.metrics.PDR),'Fresh run','green')}${kpi('MEAN LATENCY',j.metrics.mean_latency_s===null?'—':fmt(j.metrics.mean_latency_s*1000,2)+' ms','Delivered packets','cyan')}${kpi('TOTAL ENERGY',fmt(j.metrics.total_energy_j,3)+' J','Fresh run','amber')}</div><div class="status-list" style="margin-top:10px"><div class="status-row"><span>Algorithm / generated / delivered</span><b>${j.algorithm} · ${j.metrics.generated} / ${j.metrics.delivered}</b></div><div class="status-row"><span>Emergency PDR</span><b>${j.metrics.emergency_PDR===null?'—':pct(j.metrics.emergency_PDR)}</b></div><div class="status-row"><span>QoS / outage / reliability drops</span><b>${j.metrics.qos_drops} / ${j.metrics.outage_drops} / ${j.metrics.reliability_drops}</b></div><div class="status-row"><span>NB / 5G selections</span><b>${j.metrics.nb_selections} / ${j.metrics.fiveg_selections}</b></div>${diagnosticRows}<div class="status-row"><span>Simulated duration</span><b>${j.duration_s}s</b></div><div class="status-row"><span>Wall time</span><b>${fmt(j.wall_time_s,3)}s</b></div></div>`);
  }).catch(e=>toast(`SimPy bridge unavailable: ${e.message}`,true));
}
function walkthrough(){const steps=[['Project overview','The project models a logical edge gateway that forwards LoRaWAN-originated traffic through either an NB-IoT/LTE-EPC-style or 5G NR/5GC-style cellular backhaul.'],['Five-layer architecture','Device access, gateway boundary, management/orchestration, cellular backhaul/core, and application/data. The drawing is not a standards-complete topology.'],['Packet generation','200 logical endpoints are represented by aggregate Poisson arrivals. Telemetry is 50 bytes with a 10-second deadline; emergency is 200 bytes with a 1-second deadline.'],['QoS feasibility','Availability and deadline feasibility are checked before ranking. If no path qualifies, the packet is dropped without TOPSIS.'],['Gateway state + AHP','Emergency flag and battery threshold of 20% classify NORMAL, EMERGENCY, LOW_BATTERY or CONFLICT.'],['TOPSIS','Feasible candidates are normalized, weighted, compared with positive/negative ideals, and ranked by closeness.'],['Backhaul selection','The highest-ranked feasible path is used. Fixed NB and fixed 5G baselines do not fail over.'],['Research evidence','The archived primary dataset has 4,320 rows; adaptive AHP selected 5G in all 5,768,175 ranking calls.'],['Outage pilot','A separate five-seed pilot demonstrates fallback during 5G outage and selection of 5G after recovery.'],['Limitations','No physical radio, full protocol stack, N3IWF, ATSSS or 6G radio/core is implemented.']];let i=0;const show=()=>modal(`Project walkthrough · ${i+1}/${steps.length}`,`<span class="badge cyan">GUIDED PRESENTATION</span><h3 style="margin-top:12px">${steps[i][0]}</h3><p class="help" style="font-size:13px">${steps[i][1]}</p><div class="track" style="margin:15px 0"><div class="fill" style="width:${(i+1)/steps.length*100}%"></div></div><div class="field-row" style="justify-content:space-between"><button class="btn" data-walk="prev" ${i===0?'disabled':''}>← Previous</button><button class="btn primary" data-walk="next">${i===steps.length-1?'Finish':'Next →'}</button></div>`);walkStep=()=>{i=Math.min(steps.length-1,i+1);show();};window._walk={steps,show,idx:()=>i,back:()=>{i=Math.max(0,i-1);show();},next:()=>{if(i===steps.length-1)$('#modal-root').innerHTML='';else{i++;show();}}};show();}
let walkStep=null;
function bind(){const root=$('#view-root');root.onclick=e=>{const nav=e.target.closest('[data-view]');if(nav){setView(nav.dataset.view);return;}const act=e.target.closest('[data-action]')?.dataset.action;if(act){if(act==='start')start();if(act==='pause')stop();if(act==='step')stepPacket();if(act==='reset')reset();if(act==='schedule'){scheduleEvent($('#lab-event').value,Math.max(0,Number($('#lab-event-start').value)||0),Math.max(1,Number($('#lab-event-dur').value)||1));}if(act==='out-nb')manualOut('NB');if(act==='out-g5')manualOut('5G');if(act==='export-demo')demoCsv();if(act==='simpy-run')startFreshSimpy();if(act==='simpy-tsc')startFreshSimpy('TSC');if(act==='di-calc')evaluateInspector();if(act==='export-primary')csvDownload('data/primary_results/raw_paired_metrics.csv','raw_paired_metrics.csv');if(act==='export-scenario')exportScenario();if(act==='download-manifest')download('lpwan_edge_manifest.json',JSON.stringify({source:D.source,primary:'4,320 rows',supplementary:'separate 30 row 5G outage pilot',boundary:'browser demo results are not merged with archived results'},null,2),'application/json');if(act==='download-primary')csvDownload('data/primary_results/raw_paired_metrics.csv','raw_paired_metrics.csv');if(act==='download-paired')csvDownload('data/primary_results/paired_stats.csv','paired_stats.csv');if(act==='download-selection')csvDownload('data/primary_results/selection_analysis.csv','selection_analysis.csv');if(act==='walkthrough')walkthrough();return;}const layer=e.target.closest('[data-layer]');if(layer){inspectLayer(Number(layer.dataset.layer));return;}const node=e.target.closest('[data-node]');if(node){nodeModal(node.dataset.node);return;}const sc=e.target.closest('[data-scenario]');if(sc){scenario=sc.dataset.scenario;render();return;}const packet=e.target.closest('[data-packet]');if(packet){inspectPacket(packet.dataset.packet);return;}const qa=e.target.closest('[data-qa]');if(qa){qa.classList.toggle('open');return;}};
root.onchange=e=>{const t=e.target;if(t.id==='lab-algo')demo.algorithm=t.value;if(t.id==='lab-seed'){const n=Number(t.value);if(Number.isInteger(n)&&n>=0&&n<=2147483647){stop();demo=initDemo(n);render();}else toast('Seed must be an integer from 0 to 2,147,483,647.',true);}if(t.id==='lab-duration'){const n=Number(t.value);if(n>=10&&n<=3600){demo.duration=n;render();}else toast('Duration must be 10–3,600 seconds.',true);}if(t.id==='lab-speed'){demo.speed=Number(t.value);if(demo.running){stop();start();}else render();}if(t.id==='lab-arrival'){demo.arrival=Number(t.value);render();}if(t.id==='lab-emergency'){demo.emergencyRatio=Number(t.value)/100;render();}if(t.id==='lab-battery'){demo.battery=Number(t.value);render();}if(t.id==='lab-nb-rel'){demo.nbRel=Number(t.value);render();}if(t.id==='lab-g5-rel'){demo.g5Rel=Number(t.value);render();}if(t.id==='lab-animation'){demo.showPackets=t.checked;render();}if(t.id==='lab-scenario'&&t.value)randomScenario(t.value);if(t.id==='di-type'||t.id==='di-algo'||t.id==='di-nb'||t.id==='di-g5')evaluateInspector();if(t.id==='di-bat'){ $('#di-bat-value').textContent=t.value+'%';evaluateInspector();}if(t.id==='scenario-category'){window.scenarioCat=t.value;render();}if(t.id==='viva-search'){vivaTerm=t.value;const y=scrollY;render();$('#viva-search').focus();$('#viva-search').setSelectionRange(vivaTerm.length,vivaTerm.length);scrollTo(0,y);}};}
function inspectLayer(i){const defs=[['Device layer','200 logical IoT sources generate telemetry and emergency traffic using one aggregate Poisson arrival process.','Per-device LoRaWAN PHY/MAC, airtime, collisions and deduplication are abstracted.'],['Gateway / access','Logical gateway and network-server boundary receives and aggregates LoRaWAN-originated packets.','No detailed network-server implementation is connected.'],['Edge management / orchestration','CPU queue, packet classification, battery-state determination, QoS filtering, AHP weights and TOPSIS selection.','Implemented in the original Python source and mirrored by the browser decision engine.'],['Cellular backhaul / core','Two logical candidates: NB-IoT/LTE-EPC-style and 5G NR/gNB/5GC-style.','Serial modem abstractions with separate queues, availability, state, setup, service and energy.'],['Application / data','Logical cloud sink records delivered packets and outcomes.','No deployed cloud endpoint is connected.']];const x=defs[i-1];if(x)$('#layer-detail').innerHTML=`<span class="badge violet">LAYER ${i}</span><h3 style="margin:10px 0">${x[0]}</h3><p class="help">${x[1]}</p><div class="callout warn">Implementation boundary: ${x[2]}</div>`;}
function nodeModal(id){const p=D.backhauls[id];modal(id==='NB'?'NB-IoT / LTE-EPC-style':'5G NR / gNB / 5GC-style',`<div class="grid two">${Object.entries({'Bandwidth':id==='NB'?'66 kbps':'100 Mbps','Base latency':p.base_latency_s+'s','Wake/setup delay':p.setup_delay_s+'s','Setup energy':p.setup_energy_j+'J','Transmit power':p.tx_power_w+'W','Configured reliability':p.reliability_pct+'%','Idle-tail timer':p.idle_tail_s+'s','Queue capacity':'500 packets'}).map(x=>`<div class="control"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div><div class="callout warn" style="margin-top:12px">Illustrative simulator settings, not universal network specifications or measured modem profiles.</div>`);}
function manualOut(id){const prop=id==='NB'?'nbAvail':'g5Avail',m=demo.modem[id];demo[prop]=!demo[prop];m.available=demo[prop];if(!m.available){for(const t of m.tasks){if(t.status!=='DONE'){t.packet.status='DROP_OUTAGE';t.status='DONE';demo.outage++;}}m.tasks=[];m.busyUntil=demo.time;evt(`${id} disabled manually`,'Manual browser demonstration toggle.','danger');}else{m.state='SLEEP';evt(`${id} restored manually`,'Manual browser demonstration toggle.','success');}render();}
function exportScenario(){const rows=D.scenario_results.filter(x=>x.Scenario===scenario);const keys=Object.keys(rows[0]||{});const text=[keys.join(','),...rows.map(r=>keys.map(k=>JSON.stringify(r[k]??'')).join(','))].join('\n');download(`${scenario}_recorded_summary.csv`,text,'text/csv');}
function validateAppData(data){
  const required=['source','algorithm_order','algorithms','weights','backhauls','gateway','baseline','load_sweep','reliability_sensitivity','overhead','outage_summary','scenario_meta','scenario_results','limitations','tsc_matrix'];
  const missing=required.filter(key=>!(key in (data||{})));
  if(missing.length)throw new Error(`Dataset is missing required sections: ${missing.join(', ')}`);
  if(data.source.primary_rows!==4320||data.baseline.length!==6||data.algorithm_order.length!==6)throw new Error('Dataset integrity check failed: expected 4,320 primary rows and six baseline strategies.');
  if(!data.backhauls.NB||!data.backhauls['5G']||!data.gateway.telemetry_bytes||!data.tsc_matrix.paired_traces)throw new Error('Dataset is incomplete: gateway, backhaul or TSC records are missing.');
  return data;
}
function showStartupFailure(title,error,detail){
  const target=$('#view-root');
  const msg=error&&error.message?error.message:String(error||'Unknown error');
  target.innerHTML=`<div class="panel"><div class="panel-head"><div><h3>${esc(title)}</h3><div class="panel-sub">The dashboard could not finish initialising.</div></div><span class="badge red">STARTUP ERROR</span></div><div class="callout danger"><b>${esc(msg)}</b></div><p class="help" style="margin-top:12px">${esc(detail||'Check the local server terminal for the underlying error.')}</p><div class="section-actions"><button class="btn primary" id="retry-dashboard">Retry dashboard</button><a class="btn" href="/healthz" target="_blank" rel="noopener">Check local server health ↗</a></div></div>`;
  const retry=$('#retry-dashboard');if(retry)retry.onclick=()=>window.location.reload();
}
async function init(){
  let theme='dark';try{theme=localStorage.getItem('lpwan-theme')||'dark';}catch(_){/* Storage is optional. */}
  document.documentElement.dataset.theme=theme;
  $('#sidebar').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view);});
  $('#theme-toggle').onclick=()=>{const n=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=n;try{localStorage.setItem('lpwan-theme',n);}catch(_){/* Theme still changes for this session. */}};
  $('#full-toggle').onclick=()=>document.fullscreenElement?document.exitFullscreen?.():document.documentElement.requestFullscreen?.();
  $('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');
  $('#modal-root').onclick=e=>{if(e.target.closest('[data-close]'))$('#modal-root').innerHTML='';if(e.target.closest('[data-walk="prev"]'))window._walk?.back();if(e.target.closest('[data-walk="next"]'))window._walk?.next();};
  setInterval(()=>$('#wall-clock').textContent=new Date().toLocaleTimeString('en-IN',{hour12:false}),1000);
  const dataUrl=new URL(DATA,window.location.href);
  let payload;
  try{
    const response=await fetch(dataUrl.href,{cache:'no-store'});
    if(!response.ok)throw new Error(`Dataset request failed (HTTP ${response.status}) at ${dataUrl.pathname}`);
    payload=validateAppData(await response.json());
  }catch(error){
    console.error('LPWAN dashboard data load failed:',error);
    showStartupFailure('Research data could not be loaded',error,'Run start_windows.bat or py -3.13 run_app.py from the Simulation folder. Do not open frontend/index.html directly. Confirm that frontend/data/app-data.json exists and that the local server terminal has no port or permission error.');
    const label=$('#ready-label');if(label)label.textContent='DATA UNAVAILABLE';
    return;
  }
  D=payload;demo=initDemo();
  try{
    render();bind();
    const label=$('#ready-label');if(label)label.textContent='DATA READY';
  }catch(error){
    console.error('LPWAN dashboard render failed:',error);
    const label=$('#ready-label');if(label)label.textContent='RENDER ERROR';
    showStartupFailure('Dashboard rendering failed',error,'The JSON dataset was loaded successfully, but one of the dashboard views failed to initialise. Check the app.js version in the extracted Simulation folder.');
  }
}
document.addEventListener('DOMContentLoaded',init);
